def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, 50.0))
        return float(min(budget, 18.0))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= 700:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    if no_water_days >= 2 or hp <= 2:
        bid = max(72.0, highest_prev * 0.72)
        if tight_supply:
            bid = max(bid, highest_prev * 0.82, 88.0)
        return float(min(budget, bid))

    if no_water_days == 1 or hp <= 4:
        bid = max(48.0, avg_prev * 0.62)
        if tight_supply:
            bid = max(bid, highest_prev * 0.68, 62.0)
        elif loose_supply:
            bid = min(bid, 52.0)
        return float(min(budget, bid))

    bid = 24.0
    if tight_supply:
        bid = max(36.0, avg_prev * 0.45)
        if rich_count >= 2:
            bid = max(bid, 44.0)
    elif loose_supply:
        bid = 16.0
    else:
        bid = max(22.0, avg_prev * 0.28)

    if highest_prev >= 120:
        bid = min(bid, 38.0)
    elif highest_prev >= 90:
        bid = min(max(bid, 28.0), 42.0)
    elif highest_prev <= 20 and desperate_count == 0:
        bid = max(bid, 26.0)

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid = min(bid, 22.0)

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid conservatively to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine a base bid
    base_bid = DAILY_SALARY * 0.6 # Start with a reasonable bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If my HP is low, I need water desperately, bid very aggressively
        if my_status['hp'] <= 3:
            # Bid slightly above the highest previous bid, or a high percentage of salary
            return min(my_status['budget'], max(highest_prev_bid + 2.0, DAILY_SALARY * 0.9))

        # If highest previous bid was very high (e.g., from Alex/David)
        if highest_prev_bid >= DAILY_SALARY * 0.85: # 150 * 0.85 = 127.5
            # If my HP is good, I can afford to be slightly less aggressive, but still competitive
            if my_status['hp'] > 5:
                return min(my_status['budget'], max(DAILY_SALARY * 0.75, highest_prev_bid + 1.0))
            else: # HP is somewhat low, need to be more aggressive
                return min(my_status['budget'], max(DAILY_SALARY * 0.85, highest_prev_bid + 1.5))

        # If highest previous bid was moderate
        else:
            # Bid slightly above it to secure water, but not excessively high
            return min(my_status['budget'], max(base_bid, highest_prev_bid + 1.5))

    # If no previous bids from alive opponents (e.g., first day or all died)
    # Or if the above conditions didn't trigger, use a default strategy
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    elif my_status['hp'] <= 5:
        return min(my_status['budget'], DAILY_SALARY * 0.7)
    else:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

